	Ready              bool                  `json:"ready"`
	Stale              bool                  `json:"stale"`
	ReviewOverride     bool                  `json:"review_override"`
	OverrideRationale  string                `json:"override_rationale,omitempty"`
	ReviewVerdict      ReviewVerdict         `json:"review_verdict"`
	ReviewFingerprint  string                `json:"review_fingerprint"`
	ScopeKind          string                `json:"scope_kind,omitempty"`
	Scope              string                `json:"scope,omitempty"`
	ScopeRationale     string                `json:"scope_rationale,omitempty"`
	DurationClass      string                `json:"duration_class,omitempty"`
	CostClass          string                `json:"cost_class,omitempty"`
	EvidenceRoots      []string              `json:"evidence_roots,omitempty"`
	Prerequisites      []string              `json:"prerequisites,omitempty"`
	Diagnostics        []string              `json:"diagnostics,omitempty"`
	SafeArgv           string                `json:"safe_argv,omitempty"`
	RunID              string                `json:"run_id,omitempty"`
	AuthorRunID        string                `json:"author_run_id,omitempty"`
	AuthorModel        string                `json:"author_model,omitempty"`
	AuthorChangedPaths []string              `json:"author_changed_paths,omitempty"`
	Runtime            string                `json:"runtime,omitempty"`
	Model              string                `json:"model,omitempty"`
	Duration           time.Duration         `json:"duration_ns,omitempty"`
	EffectiveTimeout   time.Duration         `json:"effective_timeout_ns,omitempty"`
	TimeoutSource      string                `json:"timeout_source,omitempty"`
	Counts             SmokeCounts           `json:"counts"`
	Evidence           []SmokeEvidence       `json:"evidence,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Tests              []SmokeTestResult     `json:"tests,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverage_mapping,omitempty"`
	NextAction         string                `json:"next_action,omitempty"`
	DryRun             bool                  `json:"dry_run"`
	DiagnosticOnly     bool                  `json:"diagnostic_only"`
	Reconciliation     bool                  `json:"reconciliation_required"`
	Publications       []gitpublish.Result   `json:"publications,omitempty"`
}

type SmokeStageState struct {
	Status             SmokeExecutionStatus  `json:"status"`
	Verdict            SmokeVerdict          `json:"verdict,omitempty"`
	Path               string                `json:"path"`
	LastRunAt          *time.Time            `json:"lastRunAt,omitempty"`
	ReviewFingerprint  string                `json:"reviewFingerprint,omitempty"`
	SmokeFingerprint   string                `json:"smokeFingerprint,omitempty"`
	RunID              string                `json:"runId,omitempty"`
	AuthorRunID        string                `json:"authorRunId,omitempty"`
	AuthorModel        string                `json:"authorModel,omitempty"`
	AuthorChangedPaths []string              `json:"authorChangedPaths,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverageMapping,omitempty"`
	EvidenceID         string                `json:"evidenceId,omitempty"`
	ReviewOverride     bool                  `json:"reviewOverride"`
	Stale              bool                  `json:"stale"`
	Reconciliation     bool                  `json:"reconciliationRequired"`
	Diagnostics        []string              `json:"diagnostics,omitempty"`
	ArtifactDigest     string                `json:"artifactDigest,omitempty"`
	InputFingerprint   string                `json:"inputFingerprint,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Evidence           []EvidenceReference   `json:"evidence,omitempty"`
	Override           *DiagnosticOverride   `json:"override,omitempty"`
	ActiveAttempt      *VerificationAttempt  `json:"activeAttempt,omitempty"`
	LastAttempt        *VerificationAttempt  `json:"lastAttempt,omitempty"`
	LastComplete       *SmokeCompletion      `json:"lastComplete,omitempty"`
}

type SmokeCompletion struct {
	Verdict            SmokeVerdict          `json:"verdict"`
	Artifact           string                `json:"artifact"`
	ArtifactDigest     string                `json:"artifactDigest"`
	InputFingerprint   string                `json:"inputFingerprint"`
	CompletedAt        time.Time             `json:"completedAt"`
	RunID              string                `json:"runId,omitempty"`
	AuthorRunID        string                `json:"authorRunId,omitempty"`
	AuthorModel        string                `json:"authorModel,omitempty"`
	AuthorChangedPaths []string              `json:"authorChangedPaths,omitempty"`
	CoverageMapping    *SmokeCoverageMapping `json:"coverageMapping,omitempty"`
	EvidenceID         string                `json:"evidenceId,omitempty"`
	Evidence           []EvidenceReference   `json:"evidence,omitempty"`
	Issues             []SmokeIssue          `json:"issues,omitempty"`
	Override           *DiagnosticOverride   `json:"override,omitempty"`
}

type SmokeError struct {
	Code, Category, Message, Guidance string
	Err                               error
}

func (e *SmokeError) Error() string {
	if e == nil {
		return ""
	}
	if e.Err != nil {
		return fmt.Sprintf("smoke %s: %s: %v", e.Category, e.Message, e.Err)
	}
	return fmt.Sprintf("smoke %s: %s", e.Category, e.Message)
}
func (e *SmokeError) Unwrap() error {
	if e == nil {
		return nil
	}
	return e.Err
}

func smokeError(code, category, message, guidance string, err error) error {
	return &SmokeError{Code: code, Category: category, Message: message, Guidance: guidance, Err: err}
}

func AsSmokeError(err error) (*SmokeError, bool) {
	var target *SmokeError
	ok := errors.As(err, &target)
	return target, ok
}

func validSmokeVerdict(v SmokeVerdict) bool {
	switch v {
	case SmokePass, SmokePassWithOpenIssues, SmokeFailVerdict, SmokeBlockedVerdict, SmokeNotApplicable:
		return true
	}
	return false
}

func validateSmokeStageState(root string, sp Sprint, state SmokeStageState, path string) error {
	switch state.Status {
	case SmokeReady, SmokeRunning, SmokeCompleted, SmokeFailed, SmokeCancelled:
	default:
		return fmt.Errorf("%w: %s: smoke has unsupported status %q", ErrFlowStateMalformed, path, state.Status)
	}
	if state.Verdict != "" && !validSmokeVerdict(state.Verdict) {
		return fmt.Errorf("%w: %s: smoke has unsupported verdict %q", ErrFlowStateMalformed, path, state.Verdict)
	}
	if state.Path != ArtifactRelPath(sp, StageSmoke) {
		return fmt.Errorf("%w: %s: smoke path mismatch", ErrFlowStateMalformed, path)
	}
	if _, err := resolveSprintContained(root, sp, state.Path); err != nil {
		return fmt.Errorf("%w: %s: unsafe smoke path: %v", ErrFlowStateMalformed, path, err)
	}
	for _, d := range state.Diagnostics {
		if len(d) > 240 {
			return fmt.Errorf("%w: %s: smoke diagnostic too long", ErrFlowStateMalformed, path)
		}
	}
	if err := validateAttempt(state.ActiveAttempt, true); err != nil {
		return fmt.Errorf("%w: %s: smoke active attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if err := validateAttempt(state.LastAttempt, false); err != nil {
		return fmt.Errorf("%w: %s: smoke last attempt: %v", ErrFlowStateMalformed, path, err)
	}
	if state.Override != nil {
		if !state.Override.Requested || !state.Override.Confirmed || strings.TrimSpace(state.Override.Rationale) == "" || len(state.Override.Rationale) > 240 || strings.ContainsAny(state.Override.Rationale, "\x00\r\n") {
			return fmt.Errorf("%w: %s: invalid diagnostic override", ErrFlowStateMalformed, path)
		}
	}
	for _, issue := range state.Issues {
		if issue.ID == "" || (issue.Status != "open" && issue.Status != "resolved") {
			return fmt.Errorf("%w: %s: invalid smoke issue", ErrFlowStateMalformed, path)
		}
	}
	if state.LastComplete != nil {
		if state.LastComplete.Artifact != ArtifactRelPath(sp, StageSmoke) || state.LastComplete.CompletedAt.IsZero() || state.LastComplete.InputFingerprint == "" || state.LastComplete.ArtifactDigest == "" {
			return fmt.Errorf("%w: %s: invalid smoke lastComplete", ErrFlowStateMalformed, path)
		}
	}
	return nil
}

package app

import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"

	"github.com/Antonio7098/ultraplan-go/internal/runcontrol"
	"github.com/Antonio7098/ultraplan-go/internal/sprint"
)

type durableOperationManager struct {
	repository runcontrol.Repository
	owner      runcontrol.Owner
	mu         sync.Mutex
	owned      map[string]*ownedDurableOperation
}

type ownedDurableOperation struct {
	fence        runcontrol.Fence
	cancel       context.CancelFunc
	stop         chan struct{}
	done         chan struct{}
	eventMu      sync.Mutex
	progressKey  string
	progressAt   time.Time
	omitted      uint64
	omittedFirst time.Time
	omittedLast  time.Time
}

// durableCLICommand is the synchronous CLI counterpart to the web/TUI
// acceptance boundary. It keeps the manager alive for the whole command and
// gives product code the cancellation-aware context owned by the durable run.
type durableCLICommand struct {
	manager  *durableOperationManager
	accepted AcceptedOperation
}

type durableOperationContextKey struct{}

type durableOperationOwnership struct {
	repository runcontrol.Repository
	fence      runcontrol.Fence
}

func beginDurableCLICommand(deps dependencies, request OperationRequest) (*durableCLICommand, error) {
	repository, _, err := runRepository(deps)
	if err != nil {
		return nil, err
	}
	manager := newDurableOperationManager(repository, deps.runControl.owner)
	accepted, err := manager.AcceptOperation(deps.ctx, Confirmation{Request: request}, "")
	if err != nil {
		return nil, classifiedCause(ExitRuntime, err, "run-control.accept")
	}
	return &durableCLICommand{manager: manager, accepted: accepted}, nil
}

func (c *durableCLICommand) Context() context.Context { return c.accepted.Context }

func (c *durableCLICommand) QAWriterToken() (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	if c == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is unavailable")
	}
	return qaOwnershipFromContext(c.accepted.Context)
}

func (c *durableCLICommand) Finish(runErr error) error {
	state := OperationComplete
	if c.accepted.Context.Err() != nil {
		state = OperationCancelled
	} else if runErr != nil {
		state = OperationFailed
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	if err := c.manager.FinishOperation(ctx, c.accepted.RunID, state, runErr); err != nil {
		return classifiedCause(ExitRuntime, err, "run-control.finish")
	}
	return nil
}

func finishDurableCLICommand(command *durableCLICommand, runErr error) error {
	if command == nil {
		return runErr
	}
	return errors.Join(runErr, command.Finish(runErr))
}

func newDurableOperationManager(repository runcontrol.Repository, owner runcontrol.Owner) *durableOperationManager {
	return &durableOperationManager{repository: repository, owner: owner, owned: make(map[string]*ownedDurableOperation)}
}

func (m *durableOperationManager) AcceptOperation(ctx context.Context, confirmation Confirmation, digest string) (AcceptedOperation, error) {
	req := confirmation.Request
	target := runcontrol.Target{
		Kind: "operation", Operation: string(req.Kind), Project: req.Project, Sprint: req.Sprint,
		Study: req.Study, Stage: req.Stage, Task: req.Task,
	}
	snapshot, err := m.repository.Accept(ctx, runcontrol.Acceptance{
		Target: target, ProductStatus: "prepared", OperationAlias: digest, ConfirmationDigest: digest,
	})
	if err != nil && digest != "" && errors.Is(err, runcontrol.ErrConflict) {
		existing, resolveErr := m.repository.ResolveOperationAlias(ctx, digest)
		if resolveErr != nil {
			return AcceptedOperation{}, errors.Join(err, resolveErr)
		}
		return AcceptedOperation{RunID: string(existing.RunID), Context: ctx, Existing: true, Lifecycle: string(existing.Lifecycle)}, nil
	}
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation acceptance: %w", err)
	}
	attempt, _, err := m.repository.Claim(ctx, runcontrol.Claim{RunID: snapshot.RunID, Owner: m.owner, Lease: runcontrol.OwnerLeaseDuration})
	if err != nil {
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation owner claim: %w", err)
	}
	fence := runcontrol.Fence{RunID: snapshot.RunID, AttemptID: attempt.ID, OwnerID: m.owner.ID, FencingGeneration: attempt.FencingGeneration}
	if _, _, err := appendRunEventWithRetry(ctx, m.repository, fence, runcontrol.EventDraft{
		Type: runcontrol.EventLifecycle, Lifecycle: runcontrol.LifecycleRunning,
		Payload: map[string]string{"lifecycle": string(runcontrol.LifecycleRunning)},
	}); err != nil {
		terminalCtx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
		_, _, _ = proposeRunTerminalWithRetry(terminalCtx, m.repository, fence, runcontrol.TerminalProposal{Outcome: runcontrol.TerminalPersistenceLost, Reason: "operation start persistence failed", ProposedBy: m.owner.ID})
		cancel()
		return AcceptedOperation{}, fmt.Errorf("persist confirmed operation start: %w", err)
	}
	operationCtx, cancel := context.WithCancel(runcontrol.WithParentRun(ctx, snapshot.RunID))
	operationCtx = context.WithValue(operationCtx, durableOperationContextKey{}, durableOperationOwnership{repository: m.repository, fence: fence})
	owned := &ownedDurableOperation{fence: fence, cancel: cancel, stop: make(chan struct{}), done: make(chan struct{})}
	m.mu.Lock()
	m.owned[string(snapshot.RunID)] = owned
	m.mu.Unlock()
	go m.controlOperation(operationCtx, owned)
	return AcceptedOperation{RunID: string(snapshot.RunID), Context: operationCtx, Lifecycle: string(runcontrol.LifecycleRunning)}, nil
}

func qaOwnershipFromContext(ctx context.Context) (sprint.QAWriterToken, func(sprint.QAWriterToken) error, error) {
	ownership, ok := ctx.Value(durableOperationContextKey{}).(durableOperationOwnership)
	if !ok || ownership.repository == nil {
		return sprint.QAWriterToken{}, nil, errors.New("durable QA ownership is missing from the operation context")
	}
	token := sprint.QAWriterToken{RunID: string(ownership.fence.RunID), OperationalAttemptID: string(ownership.fence.AttemptID), FencingGeneration: ownership.fence.FencingGeneration}
	fence := func(got sprint.QAWriterToken) error {
		if got != token {
			return runcontrol.ErrStaleFence
		}
		fenceCtx, cancel := context.WithTimeout(context.WithoutCancel(ctx), 30*time.Second)
		defer cancel()
		_, err := ownership.repository.Heartbeat(fenceCtx, ownership.fence, runControlLease)
		return err
	}
	return token, fence, nil
}

func (m *durableOperationManager) RecordOperationEvent(ctx context.Context, runID string, event OperationEvent) (bool, error) {
	m.mu.Lock()
	owned := m.owned[runID]
	m.mu.Unlock()
	if owned == nil {
		return false, runcontrol.ErrNotFound
	}
	owned.eventMu.Lock()
	defer owned.eventMu.Unlock()
	eventType := runcontrol.EventProgress
	if event.State == OperationFailed {
		eventType = runcontrol.EventWarning
	}
	key := string(eventType) + "\x00" + event.Stage + "\x00" + event.Task + "\x00" + event.PhaseState + "\x00" + event.SafeSummary + "\x00" + event.EventType + "\x00" + event.EventKind + "\x00" + event.Tool + "\x00" + event.Reason + "\x00" + event.Detail
	now := time.Now().UTC()
	elapsed := now.Sub(owned.progressAt)
	if eventType == runcontrol.EventProgress && key == owned.progressKey && elapsed >= 0 && elapsed < runcontrol.ProgressCoalesceWindow {
		if owned.omitted == 0 {
			owned.omittedFirst = now
		}
		owned.omitted++
		owned.omittedLast = now
		return false, nil
	}
	payload := map[string]string{
		"state": string(event.State), "type": event.EventType,
		"count": fmt.Sprintf("%d/%d", event.Completed, event.Total),
	}
	for key, value := range map[string]string{
		"phase_state": event.PhaseState, "summary": event.SafeSummary,
		"tool_call_id": event.ToolCallID, "tool_status": event.ToolStatus,
		"tool_arguments": event.ToolArguments, "tool_result": event.ToolResult, "tool_error": event.ToolError,
		"provider": event.Provider, "model": event.Model, "harness": event.Harness,
	} {
		if value != "" {
			payload[key] = value
		}
	}
	var omission *runcontrol.Omission
	if event.Message != "" {
		omission = &runcontrol.Omission{Reason: "presentation message omitted", Count: 1}
	}
	if owned.omitted > 0 {
		if omission == nil {
			omission = &runcontrol.Omission{Reason: "equivalent progress coalesced"}
		}
		omission.Count += owned.omitted
		omission.FirstAt, omission.LastAt = &owned.omittedFirst, &owned.omittedLast
		owned.omitted = 0
	}
	_, _, err := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{
		Type: eventType, Scope: runcontrol.EventScopeOperation, Stage: event.Stage, Task: event.Task,
		Kind: event.EventKind, Tool: event.Tool, Action: event.Action, Reason: event.Reason,
		Detail: event.Detail, Payload: payload, Omission: omission,
	})
	if err != nil {
		owned.cancel()
		return false, err
	}
	if eventType == runcontrol.EventProgress {
		owned.progressKey, owned.progressAt = key, now
	}
	return true, nil
}

func (m *durableOperationManager) controlOperation(ctx context.Context, owned *ownedDurableOperation) {
	defer close(owned.done)
	ticker := time.NewTicker(runcontrol.OwnerTickInterval)
	defer ticker.Stop()
	lastHeartbeat, lastReconcile := time.Now(), time.Now()
	for {
		select {
		case <-ctx.Done():
			return
		case <-owned.stop:
			return
		case now := <-ticker.C:
			snapshot, err := m.repository.Snapshot(ctx, owned.fence.RunID)
			if err != nil {
				owned.cancel()
				return
			}
			if snapshot.Cancellation.State == runcontrol.CancellationRequested {
				if _, _, err := m.repository.AcknowledgeCancellation(ctx, owned.fence); err != nil {
					owned.cancel()
					return
				}
				owned.cancel()
				return
			}
			if now.Sub(lastHeartbeat) >= runcontrol.HeartbeatInterval {
				if _, err := m.repository.Heartbeat(ctx, owned.fence, runcontrol.OwnerLeaseDuration); err != nil {
					owned.cancel()
					return
				}
				lastHeartbeat = now
			}
			if now.Sub(lastReconcile) >= runcontrol.ReconciliationInterval {
				if _, err := m.repository.Reconcile(ctx, runcontrol.NativeProcessProbe{}, runcontrol.ReconcileOptions{}); err != nil {
					owned.cancel()
					return
				}
				lastReconcile = now
			}
		}
	}
}

func (m *durableOperationManager) FinishOperation(ctx context.Context, runID string, state OperationState, runErr error) error {
	m.mu.Lock()
	owned := m.owned[runID]
	delete(m.owned, runID)
	m.mu.Unlock()
	if owned == nil {
		return nil
	}
	owned.eventMu.Lock()
	if owned.omitted > 0 {
		_, _, appendErr := appendRunEventWithRetry(ctx, m.repository, owned.fence, runcontrol.EventDraft{Type: runcontrol.EventOmission, Omission: &runcontrol.Omission{Reason: "equivalent progress coalesced", Count: owned.omitted, FirstAt: &owned.omittedFirst, LastAt: &owned.omittedLast}})
		if appendErr != nil && runErr == nil {
			runErr = appendErr
		}
		owned.omitted = 0
	}
	owned.eventMu.Unlock()
	close(owned.stop)
	<-owned.done
	owned.cancel()
	outcome := runcontrol.TerminalSucceeded
	reason := "operation completed"
	switch {
	case errors.Is(runErr, context.DeadlineExceeded):
		outcome, reason = runcontrol.TerminalTimedOut, "operation deadline exceeded"
	case errors.Is(runErr, context.Canceled), state == OperationCancelled:
		outcome, reason = runcontrol.TerminalCancelled, "operation cancelled"
	case runErr != nil, state == OperationFailed:
		outcome, reason = runcontrol.TerminalFailed, "operation failed"
	case state == OperationPartial:
		outcome, reason = runcontrol.TerminalInterrupted, "operation interrupted"
	}
	_, _, err := proposeRunTerminalWithRetry(ctx, m.repository, owned.fence, runcontrol.TerminalProposal{Outcome: outcome, Reason: reason, ProposedBy: m.owner.ID})
	return err
}

package sprint

import (
	"context"
	"fmt"
	"path/filepath"

	"github.com/Antonio7098/ultraplan-go/internal/platform/gitpublish"
)

func (s Service) publishPlanningStage(ctx context.Context, projectRef, sprintRef string, stage PlanningStage) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	sp, err := s.resolveMutationSprint(projectRef, sprintRef)
	if err != nil {
		return nil, err
	}
	paths := []string{filepath.Join(sp.Path, "flow-state.json")}
	if stage == StageAreaReasoning {
		inputs, readErr := s.store.ReadPlanningInputs(sp)
		if readErr != nil {
			return nil, readErr
		}
		_, _, catalog, resolveErr := s.resolveSprintInputs(projectRef, sprintRef)
		if resolveErr != nil {
			return nil, resolveErr
		}
		manifest, findings := BuildReasoningManifest(s.root, sp, inputs, catalog)
		if len(findings) > 0 {
			return nil, fmt.Errorf("git publish: area-reasoning manifest is invalid")
		}
		for _, entry := range manifest.ReasoningTemplates {
			paths = append(paths, filepath.Join(s.root, filepath.FromSlash(normalizeWorkspacePath(entry.OutputPath))))
		}
	} else {
		path, pathErr := ArtifactPath(s.root, sp, stage)
		if pathErr != nil {
			return nil, pathErr
		}
		paths = append(paths, path)
	}
	if stage == StageCodeContext {
		paths = append(paths, sprintWorkspacePath(sp))
	}
	result, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root: s.root, Paths: paths,
		Message:  fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, stage),
		Identity: fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, stage),
	})
	if result.Repository == "" && result.Skipped {
		return nil, err
	}
	return []gitpublish.Result{result}, err
}

func (s Service) publishExecuteStage(ctx context.Context, sp Sprint, target ExecuteTargetRef) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	identity := fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, StageExecute)
	message := fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, StageExecute)
	implementation, err := s.publisher.Publish(ctx, gitpublish.Request{Root: target.Path, All: true, Message: message, Identity: identity + "/implementation"})
	results := visiblePublication(implementation)
	if err != nil {
		return results, err
	}
	workspaceResult, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root: s.root,
		Paths: []string{
			filepath.Join(sp.Path, "execute.md"),
			filepath.Join(sp.Path, ".run-state.json"),
		},
		Message: message, Identity: identity + "/workspace",
	})
	results = append(results, visiblePublication(workspaceResult)...)
	return results, err
}

func (s Service) publishReviewStage(ctx context.Context, sp Sprint) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	result, err := s.publisher.Publish(ctx, gitpublish.Request{
		Root:     s.root,
		Paths:    []string{filepath.Join(sp.Path, "review.md"), filepath.Join(sp.Path, "flow-state.json")},
		Message:  fmt.Sprintf("ultraplan: sprint %s/%s complete %s", sp.Project, sp.Slug, StageReview),
		Identity: fmt.Sprintf("sprint/%s/%s/%s", sp.Project, sp.Slug, StageReview),
	})
	return visiblePublication(result), err
}

func (s Service) publishSmokeStage(ctx context.Context, prepared smokePrepared, result SmokeResult) ([]gitpublish.Result, error) {
	if s.publisher == nil {
		return nil, nil
	}
	identity := fmt.Sprintf("sprint/%s/%s/%s", prepared.Sprint.Project, prepared.Sprint.Slug, StageSmoke)
	message := fmt.Sprintf("ultraplan: sprint %s/%s complete %s", prepared.Sprint.Project, prepared.Sprint.Slug, StageSmoke)
	var results []gitpublish.Result
	if len(result.AuthorChangedPaths) > 0 {
		paths := make([]string, 0, len(result.AuthorChangedPaths))
		for _, rel := range result.AuthorChangedPaths {
			paths = append(paths, filepath.Join(prepared.HarnessRoot, filepath.FromSlash(rel)))
		}
		harness, err := s.publisher.Publish(ctx, gitpublish.Request{Root: prepared.HarnessRoot, Paths: paths, Message: message, Identity: identity + "/harness"})
		results = append(results, visiblePublication(harness)...)
		if err != nil {
			return results, err
		}
	}
	workspacePaths := []string{
		filepath.Join(prepared.Sprint.Path, "smoke.md"),
		filepath.Join(prepared.Sprint.Path, "flow-state.json"),
	}
	if result.Verdict == SmokePass && !result.DiagnosticOnly {
		workspacePaths = append(workspacePaths, filepath.Join(filepath.Dir(filepath.Dir(prepared.Sprint.Path)), "roadmap.md"))
	}
	workspaceResult, err := s.publisher.Publish(ctx, gitpublish.Request{Root: s.root, Paths: workspacePaths, Message: message, Identity: identity + "/workspace"})
	results = append(results, visiblePublication(workspaceResult)...)
	return results, err
}

func visiblePublication(result gitpublish.Result) []gitpublish.Result {
	if result.Repository == "" && result.Skipped {
		return nil
	}
	return []gitpublish.Result{result}
}

