// Reproduction: governed input changes after a completed review must make the
// review stale (TRD 18.9.3 "Any governed input ... change makes the prior
// review stale"), which is the currentness guarantee Verify relies on.
func TestGauntletInputChangeStalesCompletedReview(t *testing.T) {
	root, sp := reviewFixture(t)
	runtime := &reviewRuntime{}
	service := NewService(root).WithRuntime(runtime).WithStageRuntime(map[PlanningStage]StageRuntime{StageReview: {Model: "test/model"}})
	if _, err := service.Review(context.Background(), "proj", "01", ReviewRequest{}); err != nil {
		t.Fatal(err)
	}
	status, err := service.VerificationStatus("proj", "01")
	if err != nil || !status.Review.Fresh {
		t.Fatalf("baseline status=%+v err=%v", status.Review, err)
	}
	writeFileContent(t, sp.Path, "# Requirements\n\nReview this sprint.\n\nChanged acceptance: new clause after review completion.\n", "requirements.md")
	status, err = service.VerificationStatus("proj", "01")
	if err != nil {
		t.Fatal(err)
	}
	t.Logf("post-change fresh=%t reasons=%v assessment=%s resumable=%t", status.Review.Fresh, status.Review.FreshnessReasons, status.Assessment, status.Review.Resumable)
	if status.Review.Fresh {
		t.Errorf("governed input change did not stale the completed review: reasons=%v", status.Review.FreshnessReasons)
	}
	if _, err := service.RunSmoke(context.Background(), "proj", "01", SmokeRequest{DryRun: true}); err != nil {
		smokePreparedErr := err
		t.Logf("smoke preflight after input change: %v", smokePreparedErr)
	}
	_ = filepath.Join
}
EOF
